const rentalInitial=()=>({items:{},period:'day',start:'',end:'',fulfilment:'Collection',address:'',name:'',email:'',phone:'',notes:'',step:'kit',ack:false});
const bundles={bundle:['fx3','sigma24','matte','nd','tripod'],modifiers:['lantern','dome','octa','rectangle'],gopros:['gopro']};
function includedBy(s,id){return Object.entries(bundles).find(([parent,parts])=>s.items[parent]>0&&parts.includes(id))?.[0]||''}
function setRentalQty(s,id,value){const item=rentalItems.find(i=>i.id===id);if(!item||includedBy(s,id))return s;const n={...s,items:{...s.items}};const count=Math.max(0,Math.min(item.qty,Number.isFinite(value)?Math.floor(value):0));if(count)n.items[id]=count;else delete n.items[id];if(count&&bundles[id])for(const part of bundles[id])delete n.items[part];return n}
function rentalDays(s){if(!validDate(s.start)||!validDate(s.end))return 0;const a=Date.parse(s.start),b=Date.parse(s.end);if(!Number.isFinite(a)||!Number.isFinite(b)||b<a)return 0;return Math.round((b-a)/86400000)+1}
function rentalUnits(s){const days=rentalDays(s);return !days?0:s.period==='week'?Math.ceil(days/7):s.period==='half'?1:days}
function rentalErrors(s,today){const e=[];if(!Object.keys(s.items).length)e.push('Choose at least one item.');if(!rentalDays(s))e.push('Choose valid start and return dates.');if(today&&s.start<today)e.push('Choose today or a later start date.');const d=rentalDays(s);if(s.period==='half'&&d>1)e.push('Half-day hire must start and return on the same date.');if(s.period==='week'&&d>0&&d<5)e.push('Weekly hire is for 5–7 days. Choose daily hire for a shorter rental.');if(s.fulfilment==='Delivery'&&!s.address.trim())e.push('Add the delivery town or address.');return e}
function rentalLines(s){const units=rentalUnits(s);return rentalItems.filter(i=>s.items[i.id]>0&&!includedBy(s,i.id)).map(i=>({id:i.id,title:i.title,qty:s.items[i.id],rate:i[s.period],units,amount:i[s.period]*s.items[i.id]*units}))}
const rentalTotal=s=>rentalLines(s).reduce((sum,i)=>sum+i.amount,0);
function restoreRental(raw){let s=rentalInitial();if(!raw||typeof raw!=='object')return s;if(['half','day','week'].includes(raw.period))s.period=raw.period;for(const key of ['start','end','address','name','email','phone','notes'])if(typeof raw[key]==='string')s[key]=raw[key].slice(0,key==='notes'?1500:200);if(raw.fulfilment==='Delivery')s.fulfilment='Delivery';for(const i of rentalItems)if(raw.items&&Number.isInteger(raw.items[i.id]))s=setRentalQty(s,i.id,raw.items[i.id]);if(['kit','dates','review'].includes(raw.step))s.step=raw.step;return s}
function rentalBrief(s){return ['VISIONHAUS EQUIPMENT RENTAL REQUEST',`Name: ${s.name}`,`Email: ${s.email}`,`Phone: ${s.phone||'Not supplied'}`,'',`Dates: ${s.start} to ${s.end} (${rentalDays(s)} calendar days)`,`Rate: ${s.period==='half'?'Half day, up to 4 hours':s.period==='week'?'Weekly, 5–7 days per block':'Daily'}`,`${s.fulfilment}${s.fulfilment==='Delivery'&&s.address?`: ${s.address}`:''}`,'',...rentalLines(s).map(l=>`${l.title} × ${l.qty} × ${l.units} rate unit(s): N$ ${l.amount.toLocaleString('en-NA')}`),'',`Equipment estimate: N$ ${rentalTotal(s).toLocaleString('en-NA')} ex VAT`,'Delivery, deposit and insurance excluded. Availability and eligibility require approval.',`Notes: ${s.notes||'None'}`,'This is a rental request, not a confirmed reservation.'].join('\n')}


const emailPattern=/^[^\s<>@\r\n]+@[^\s<>@\r\n]+\.[^\s<>@\r\n]+$/;
const safeLine=value=>String(value||'').replace(/[\r\n\u0000-\u001f]/g,' ').trim();
const json=(status,body)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const attempts=new Map();

// A bounded, per-worker abuse guard. Not a globally shared availability or request store.
function allowRequest(key){
 const now=Date.now();
 if(attempts.size>2000)for(const [ip,entry]of attempts)if(now-entry.start>600000)attempts.delete(ip);
 if(attempts.size>4000)attempts.clear();
 const entry=attempts.get(key);
 if(!entry||now-entry.start>600000){attempts.set(key,{start:now,count:1});return true}
 if(entry.count>=6)return false;
 entry.count++;return true;
}
async function handleSubmission(request,env){
 const origin=new URL(request.url).origin;
 if(request.method!=='POST')return json(405,{error:'Use Submit to send your request.'});
 if(request.headers.get('Origin')!==origin)return json(403,{error:'Please submit from the VisionHaus app.'});
 if(!request.headers.get('Content-Type')?.startsWith('application/json'))return json(415,{error:'Invalid request format.'});
 const length=Number(request.headers.get('Content-Length')||0);
 if(length>40000)return json(413,{error:'Your request is too long. Please shorten the notes.'});
 let raw;
 try{
  const reader=request.body?.getReader();if(!reader)return json(400,{error:'Your request is empty.'});
  const chunks=[];let size=0;
  for(;;){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>40000){await reader.cancel();return json(413,{error:'Your request is too long.'})}chunks.push(value)}
  const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength}
  raw=JSON.parse(new TextDecoder().decode(bytes));
 }catch{return json(400,{error:'Please check the request and try again.'})}
 if(!raw||!['production','rental'].includes(raw.type)||!raw.state||typeof raw.state!=='object'||Array.isArray(raw.state))return json(400,{error:'Your request is incomplete.'});
 if(raw.website)return json(400,{error:'Please try again.'});
 if(typeof raw.requestId!=='string'||!/^vh-[a-f0-9]{64}$/.test(raw.requestId))return json(400,{error:'Please refresh the page and try submitting again.'});
 if(typeof raw.state.name!=='string'||typeof raw.state.email!=='string')return json(400,{error:'Add your name and a valid email address.'});
 const name=safeLine(raw.state.name),email=safeLine(raw.state.email),phone=safeLine(raw.state.phone);
 if(name.length<2||name.length>100||email.length>150||!emailPattern.test(email)||phone.length>150)return json(400,{error:'Add your name and a valid email address.'});
 if(typeof raw.state.notes==='string'&&raw.state.notes.length>6000)return json(400,{error:'Please limit your notes to 6,000 characters.'});
 let state,brief;
 if(raw.type==='rental'){
  state=restoreRental(raw.state);
  const today=windhoekToday();
  const errors=rentalErrors(state,today);
  if(errors.length)return json(400,{error:errors.join(' ')});
  if(raw.state.ack!==true)return json(400,{error:'Confirm that you understand this is a rental request.'});
  Object.assign(state,{name,email,phone});brief=rentalBrief(state);
 }else{
  state=restore(raw.state);
  const errors=productionErrors(state);
  if(errors.length)return json(400,{error:errors.join(' ')});
  Object.assign(state,{name,email,phone});brief=briefText(state);
 }
 // Prepare validated fields. Web3Forms free-plan sends must originate in the browser.
 // The public form access key routes to its configured inbox.
 if(!env.WEB3FORM_ACCESS_KEY)return json(503,{error:'Online submission is temporarily unavailable. Your draft is saved on this device. Please try again later.'});
 if(!allowRequest(request.headers.get('CF-Connecting-IP')||'anonymous'))return json(429,{error:'Too many attempts. Please wait a few minutes before trying again.'});
 const reference=`VH-${raw.requestId.slice(3,15).toUpperCase()}`;
 return json(200,{reference,form:{access_key:env.WEB3FORM_ACCESS_KEY,name,email,phone,subject:`${raw.type==='rental'?'Rental':'Production'} request · ${reference} · ${name}`,message:`New client request\nReference: ${reference}\nReply to this email to contact ${name}.\n\n${brief}`,botcheck:false}});
}

const assets={"/app.js":{"body":"","type":"text/javascript; charset=utf-8"},"/dates.mjs":{"body":"","type":"text/javascript; charset=utf-8"},"/domain.mjs":{"body":"","type":"text/javascript; charset=utf-8"},"/icon-192.png":{"body":"","type":"image/png"},"/icon-512.png":{"body":"","type":"image/png"},"/icon.svg":{"body":"","type":"image/svg+xml"},"/index.html":{"body":"","type":"text/html; charset=utf-8"},"/manifest.webmanifest":{"body":"","type":"application/manifest+json"},"/rentals.mjs":{"body":"","type":"text/javascript; charset=utf-8"},"/style.css":{"body":"","type":"text/css; charset=utf-8"},"/submission.mjs":{"body":"","type":"text/javascript; charset=utf-8"},"/sw.js":{"body":"","type":"text/javascript; charset=utf-8"},"/vendor/LUCIDE-LICENSE":{"body":"","type":"application/octet-stream"},"/vendor/lucide.min.js":{"body":"","type":"text/javascript; charset=utf-8"}};
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/requests')return handleSubmission(request,env);if(url.pathname.startsWith('/api/'))return new Response('Not found',{status:404});if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const asset=assets[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});const bytes=Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Cache-Control':'no-cache'}})}};
